const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{height:100%;box-sizing:border-box;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;cursor:pointer;border:0;background:none;padding:0;margin:0}\n.card button:disabled{cursor:default}\n.card :focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.tb{height:100%;display:flex;flex-direction:column;gap:6px;padding:8px;min-height:0;min-width:0}\n\n/* \u9876\u90e8 */\n.top{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.hd{display:flex;align-items:center;gap:8px;flex:none}\n.ttl{flex:1;min-width:0}\n.ttl b{display:block;font-size:15px;line-height:1.2}\n.ttl small{display:block;font-size:11px;color:var(--muted)}\n.add{flex:none;height:30px;min-width:30px;padding:0 12px;border-radius:15px;background:var(--accent);color:var(--on-accent);font-weight:600;display:flex;align-items:center;justify-content:center;gap:4px}\n.plus{font-size:18px;line-height:1;margin-top:-1px}\n.top .add{padding:0;width:30px}\n.top .addlb{display:none}\n.tb[data-size=\"6x3\"] .top .add{width:auto;padding:0 12px}\n.tb[data-size=\"6x3\"] .top .addlb{display:inline}\n.pt{font-size:11px;color:var(--muted);white-space:nowrap}\n.top>.pt{flex:1;text-align:right;min-width:0}\n.prog{display:flex;align-items:center;gap:8px;flex:none}\n.bar{flex:1;height:6px;border-radius:3px;background:var(--soft);overflow:hidden;display:block}\n.fill{display:block;height:100%;background:var(--accent);border-radius:3px}\n.chips,.fchips{display:flex;gap:4px;overflow-x:auto;flex:none;scrollbar-width:none}\n.chips::-webkit-scrollbar,.fchips::-webkit-scrollbar{display:none}\n.fchips{flex-wrap:wrap;overflow:visible}\n.chip{flex:none;height:24px;padding:0 10px;border-radius:12px;border:1px solid var(--line);font-size:11px;background:transparent;white-space:nowrap}\n.chip.on{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}\n\n/* \u6807\u7b7e\u9875 */\n.tabs{display:flex;gap:3px;background:var(--soft);padding:3px;border-radius:11px;min-width:0;flex:1}\n.hd~.tabs{flex:none}\n.tab{flex:1;min-width:0;height:36px;display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:8px;color:var(--muted);font-size:11px;line-height:1.15}\n.tab .tc{font-size:14px;font-weight:700;color:inherit}\n.tab.on{background:var(--accent);color:var(--on-accent)}\n.tb[data-size=\"6x3\"] .tabs{flex:none;width:250px}\n.tb[data-size=\"6x3\"] .tab{flex-direction:row;gap:5px;height:28px;font-size:12px}\n.tb[data-size=\"6x3\"] .tab .tc{font-size:12px}\n.flash{animation:tbflash .9s ease-out 1}\n@keyframes tbflash{0%{box-shadow:0 0 0 0 var(--accent)}60%{box-shadow:0 0 0 5px transparent}100%{box-shadow:0 0 0 0 transparent}}\n\n/* \u5217\u8868\u4e0e\u5361\u7247 */\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;scrollbar-width:thin}\n.tk{flex:none;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;padding:7px 8px;display:flex;flex-direction:column;gap:6px;min-width:0}\n.tk-main{min-width:0;cursor:pointer;border-radius:6px}\n.tk-title{font-weight:600;overflow-wrap:anywhere;word-break:break-word}\n.tk.st-done .tk-title{text-decoration:line-through;color:var(--muted);font-weight:500}\n.tk-meta{display:flex;flex-wrap:wrap;gap:4px;margin-top:4px}\n.tag{font-size:10.5px;line-height:1.3;padding:1px 7px;border-radius:9px;background:var(--soft);color:var(--ink);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tag.due.late{background:var(--accent);color:var(--on-accent);font-weight:700}\n.tag.due.soon{border:1px solid var(--accent);font-weight:600}\n.tag.due.ok{color:var(--muted)}\n.tk-ops{display:flex;gap:4px;min-width:0}\n.op{flex:1;min-width:0;height:26px;border-radius:7px;background:var(--soft);display:flex;align-items:center;justify-content:center;gap:3px;font-size:11px;white-space:nowrap;padding:0 4px}\n.op .ic{font-size:14px;line-height:1}\n.op.nx{background:var(--accent);color:var(--on-accent)}\n.op.ud{flex:none;width:28px}\n.op:disabled{opacity:.3}\n.op.ph{visibility:hidden}\n.empty{margin:auto;text-align:center;color:var(--muted);font-size:12px;padding:10px;display:flex;flex-direction:column;gap:8px;align-items:center}\n.err{flex:none;font-size:11px;color:var(--accent);font-weight:600;overflow-wrap:anywhere}\n\n/* 6x3\uff1a\u5bbd\u884c */\n.tb[data-size=\"6x3\"] .tk{flex-direction:row;align-items:center;gap:8px}\n.tb[data-size=\"6x3\"] .tk-main{flex:1}\n.tb[data-size=\"6x3\"] .tk-ops{flex:none}\n.tb[data-size=\"6x3\"] .op{flex:none;min-width:28px;padding:0 7px}\n\n/* 6x6\uff1a\u4e09\u5217\u770b\u677f */\n.cols{flex:1;min-height:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}\n.col{display:flex;flex-direction:column;min-height:0;min-width:0;background:var(--soft);border-radius:11px;padding:5px}\n.col-hd{display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:700;padding:1px 3px 5px;flex:none}\n.cnt{font-size:11px;font-weight:700;min-width:18px;text-align:center;border-radius:9px;background:var(--panel-paper);padding:0 5px}\n.cols .tk{padding:6px}\n.cols .tk-title{font-size:12.5px}\n.cols .lb,.cols .op.ph{display:none}\n.cols .op{padding:0}\n.cols .op .ic{font-size:15px}\n.cols .op.ud{flex:1;width:auto}\n\n\n/* \u8868\u5355 */\n.fm{gap:6px}\n.fm-hd{display:flex;align-items:center;gap:8px;flex:none}\n.fm-t{font-size:14px}\n.back{height:26px;padding:0 10px;border-radius:13px;background:var(--soft);font-size:12px}\n.fm-body{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:9px;padding-right:2px;scrollbar-width:thin}\n.fld{display:flex;flex-direction:column;gap:4px;min-width:0}\n.lab{font-size:11px;color:var(--muted)}\n.inp{width:100%;height:32px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);padding:0 8px;font:inherit;min-width:0}\n.inp::placeholder{color:var(--muted)}\n.seg{display:flex;gap:3px;background:var(--soft);padding:3px;border-radius:10px}\n.sg{flex:1;min-width:0;height:26px;border-radius:7px;font-size:12px;color:var(--muted)}\n.sg.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.chk{display:flex;align-items:center;gap:6px;font-size:12px;min-height:28px}\n.chk input{width:16px;height:16px;margin:0;accent-color:var(--accent)}\n.fm-ft{display:flex;gap:6px;flex:none}\n.btn{flex:1;height:34px;padding:0 14px;border-radius:10px;background:var(--soft);font-weight:600}\n.btn.primary{background:var(--accent);color:var(--on-accent)}\n.btn.danger{background:transparent;border:1px solid var(--accent);color:var(--accent)}\n.btn.danger.on{background:var(--accent);color:var(--on-accent)}\n.empty .btn{flex:none}\n.tb[data-size=\"6x3\"] .fm-body,.tb[data-size=\"6x6\"] .fm-body{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:9px 12px;align-content:start}\n.fld.wide{grid-column:1/-1}\n.tb[data-size=\"3x3\"] .fm-body{gap:7px}\n.tb[data-size=\"3x3\"] .inp{height:30px}\n.tb[data-size=\"3x3\"] .btn{height:30px}\n";
const COLS=[{k:'todo',n:'待做'},{k:'doing',n:'进行中'},{k:'done',n:'已完成'}];
function stIdx(k){const i=COLS.findIndex(x=>x.k===k);return i<0?0:i;}
function listOf(s){return s&&Array.isArray(s.tasks)?s.tasks:[];}
function withTasks(s,tasks){return Object.assign({},s||{},{tasks:tasks});}
function p2(n){return n<10?'0'+n:''+n;}
function parseDay(d){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(d||'');return m?Date.UTC(+m[1],+m[2]-1,+m[3]):null;}
function fmtDay(ms){const t=new Date(ms);return t.getUTCFullYear()+'-'+p2(t.getUTCMonth()+1)+'-'+p2(t.getUTCDate());}
function addDays(d,n){const a=parseDay(d);return a==null?d:fmtDay(a+n*86400000);}
function weekDow(d){const a=parseDay(d);return a==null?0:(new Date(a).getUTCDay()+6)%7;}
function mdOf(d){return d?d.slice(5).replace('-','/'):'';}

function dueInfo(t,today){
  if(!t.due)return null;
  const a=parseDay(t.due),b=parseDay(today);
  if(a==null||b==null)return {text:t.due,cls:''};
  const diff=Math.round((a-b)/86400000);
  if(t.status==='done')return {text:'截止 '+mdOf(t.due),cls:'ok'};
  if(diff<0)return {text:'逾期'+(-diff)+'天',cls:'late'};
  if(diff===0)return {text:'今天截止',cls:'soon'};
  if(diff===1)return {text:'明天截止',cls:'soon'};
  return {text:'截止 '+mdOf(t.due),cls:''};
}

function placeTask(rest,nt,front){
  const arr=rest.slice();
  let idx=-1;
  if(front){idx=arr.findIndex(x=>x.status===nt.status);}
  else{for(let i=arr.length-1;i>=0;i--){if(arr[i].status===nt.status){idx=i+1;break;}}}
  if(idx<0)idx=arr.length;
  arr.splice(idx,0,nt);
  return arr;
}

function moveTo(s,id,to){
  const all=listOf(s);
  const t=all.find(x=>x.id===id);
  if(!t||t.status===to)return s;
  const rest=all.filter(x=>x.id!==id);
  return withTasks(s,placeTask(rest,Object.assign({},t,{status:to}),true));
}

// dir: -1 前移一位, 1 后移一位, 'top' 排到最前；vis 为当前可见任务 id 集合（筛选项目时只在可见任务间换位）
function nudge(s,id,dir,vis){
  const all=listOf(s);
  const cur=all.find(x=>x.id===id);
  if(!cur)return s;
  const col=all.filter(x=>x.status===cur.status);
  const v=col.filter(x=>!vis||vis.has(x.id));
  const p=v.findIndex(x=>x.id===id);
  const q=dir==='top'?0:p+dir;
  if(p<0||q<0||q>=v.length||q===p)return s;
  const target=v[q].id;
  const from=col.findIndex(x=>x.id===id);
  const item=col.splice(from,1)[0];
  let to=col.findIndex(x=>x.id===target);
  if(dir===1)to+=1;
  col.splice(to,0,item);
  let n=0;
  return withTasks(s,all.map(x=>x.status===cur.status?col[n++]:x));
}

function applyDraft(s,d){
  const title=(d.title||'').trim();
  const project=(d.project||'').trim();
  const due=d.due||'';
  const all=listOf(s);
  if(!d.isNew){
    const old=all.find(x=>x.id===d.id);
    if(!old)return s;
    let ns=withTasks(s,all.map(x=>x.id===d.id?Object.assign({},x,{title:title,project:project,due:due}):x));
    if(old.status!==d.status)ns=moveTo(ns,d.id,d.status);
    if(d.front)ns=nudge(ns,d.id,'top',null);
    return ns;
  }
  if(all.some(x=>x.id===d.id))return s;
  const nt={id:d.id,title:title,project:project,due:due,status:d.status||'todo',created:d.created};
  return withTasks(s,placeTask(all,nt,!!d.front));
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent,size}=ctx;
  const today=day();
  const tasks=listOf(state);
  const C=(...a)=>a.filter(x=>x!=null&&x!==false);
  const flash=ui.flash||'';
  ui.flash='';
  const tall=size==='3x6'||size==='6x6';
  const projects=[];
  tasks.forEach(t=>{if(t.project&&!projects.includes(t.project))projects.push(t.project);});
  const hasNone=tasks.some(t=>!t.project);
  let proj=tall?(ui.proj||''):'';
  if(proj==='__none'&&!(hasNone&&projects.length))proj='';
  if(proj&&proj!=='__none'&&!projects.includes(proj))proj='';
  const vis=tasks.filter(t=>!proj||(proj==='__none'?!t.project:t.project===proj));
  const visSet=new Set(vis.map(t=>t.id));
  const colOf=k=>vis.filter(t=>t.status===k);
  const curCol=COLS.some(x=>x.k===ui.col)?ui.col:'todo';

  function openNew(){
    ui.draft={title:'',project:(proj&&proj!=='__none')?proj:'',due:'',status:'todo',front:false};
    ui.view='form';ui.confirmDel=false;ui.formErr='';ui.err='';redraw();
  }
  function openEdit(t){
    ui.draft={id:t.id,title:t.title,project:t.project||'',due:t.due||'',status:t.status,front:false};
    ui.view='form';ui.confirmDel=false;ui.formErr='';ui.err='';redraw();
  }
  function run(fn,to){
    ui.err='';
    update(fn).then(()=>{if(to){ui.flash=to;redraw();}}).catch(()=>{ui.err='保存失败，请重试';redraw();});
  }

  function opBtn(cls,parts,label,fn,dis){
    return el('button',{type:'button',class:'op '+cls,'aria-label':label,title:label,disabled:!!dis,onclick:(e)=>{e.stopPropagation();if(!dis)fn();}},...parts);
  }
  function ph(){return el('span',{class:'op ph','aria-hidden':'true'});}

  function taskCard(t,pos,len){
    const si=stIdx(t.status);
    const due=dueInfo(t,today);
    const meta=C(
      t.project?el('span',{class:'tag proj'},t.project):null,
      due?el('span',{class:'tag due '+due.cls},due.text):null
    );
    const main=el('div',{class:'tk-main',role:'button',tabindex:'0','aria-label':'编辑任务 '+t.title,onclick:()=>openEdit(t),onkeydown:(e)=>{if(e.key==='Enter')openEdit(t);}},
      ...C(el('div',{class:'tk-title'},t.title),meta.length?el('div',{class:'tk-meta'},...meta):null));
    const prev=si>0?opBtn('pv',[el('span',{class:'ic'},'‹'),el('span',{class:'lb'},COLS[si-1].n)],'移到'+COLS[si-1].n,()=>run(s=>moveTo(s,t.id,COLS[si-1].k),COLS[si-1].k)):ph();
    const next=si<COLS.length-1?opBtn('nx',[el('span',{class:'lb'},COLS[si+1].n),el('span',{class:'ic'},'›')],'移到'+COLS[si+1].n,()=>run(s=>moveTo(s,t.id,COLS[si+1].k),COLS[si+1].k)):ph();
    const up=opBtn('ud',[el('span',{class:'ic'},'↑')],'上移，更优先',()=>run(s=>nudge(s,t.id,-1,visSet),''),pos===0);
    const dn=opBtn('ud',[el('span',{class:'ic'},'↓')],'下移，靠后',()=>run(s=>nudge(s,t.id,1,visSet),''),pos===len-1);
    return el('div',{class:'tk st-'+t.status},main,el('div',{class:'tk-ops'},prev,next,up,dn));
  }

  function emptyBox(k){
    if(!tasks.length){
      return el('div',{class:'empty'},el('div',{},'还没有任务'),el('button',{type:'button',class:'btn primary',onclick:openNew},'添加第一个任务'));
    }
    const nm=COLS.find(x=>x.k===k).n;
    if(size==='6x6')return el('div',{class:'empty'},el('div',{},'暂无任务'));
    return el('div',{class:'empty'},el('div',{},proj?'该项目下「'+nm+'」没有任务':'「'+nm+'」没有任务'));
  }

  function listFor(k,cls){
    const items=colOf(k);
    return el('div',{class:cls||'list'},...(items.length?items.map((t,i)=>taskCard(t,i,items.length)):[emptyBox(k)]));
  }

  function tabsBar(){
    return el('div',{class:'tabs',role:'tablist'},...COLS.map(x=>el('button',{type:'button',role:'tab','aria-selected':x.k===curCol?'true':'false',
      class:'tab'+(x.k===curCol?' on':'')+(flash===x.k?' flash':''),onclick:()=>{ui.col=x.k;ui.err='';redraw();}},
      el('span',{class:'tn'},x.n),el('span',{class:'tc'},String(colOf(x.k).length)))));
  }

  function addBtn(){
    return el('button',{type:'button',class:'add','aria-label':'添加任务',onclick:openNew},el('span',{class:'plus'},'+'),el('span',{class:'addlb'},'添加'));
  }

  function progress(){
    const done=tasks.filter(t=>t.status==='done').length;
    const fill=el('span',{class:'fill'});
    fill.style.width=percent(done,tasks.length)+'%';
    return el('div',{class:'prog'},el('span',{class:'bar'},fill),el('span',{class:'pt'},'已完成 '+done+'/'+tasks.length));
  }

  function weekText(){
    const d=weekDow(today);
    return '本周 '+mdOf(addDays(today,-d))+' – '+mdOf(addDays(today,6-d));
  }

  function chipsBar(){
    if(!projects.length)return null;
    const mk=(v,label)=>el('button',{type:'button',class:'chip'+(proj===v?' on':''),onclick:()=>{ui.proj=v;redraw();}},label);
    return el('div',{class:'chips'},...C(mk('','全部'),...projects.map(p=>mk(p,p)),hasNone?mk('__none','无项目'):null));
  }

  function errBox(){return ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;}

  function boardView(){
    const wrap=el('div',{class:'tb','data-size':size});
    if(size==='3x3'){
      wrap.append(...C(el('div',{class:'top'},tabsBar(),addBtn()),errBox(),listFor(curCol)));
    }else if(size==='6x3'){
      wrap.append(...C(el('div',{class:'top'},tabsBar(),el('span',{class:'pt'},tasks.length?'完成 '+tasks.filter(t=>t.status==='done').length+'/'+tasks.length:''),addBtn()),errBox(),listFor(curCol)));
    }else{
      const head=el('div',{class:'hd'},el('div',{class:'ttl'},el('b',{},'本周任务'),el('small',{},weekText())),addBtn());
      wrap.append(...C(head,tasks.length?progress():null,chipsBar(),errBox()));
      if(size==='6x6'&&!tasks.length){
        wrap.append(el('div',{class:'list'},emptyBox('todo')));
      }else if(size==='6x6'){
        wrap.append(el('div',{class:'cols'},...COLS.map(x=>el('div',{class:'col'+(flash===x.k?' flash':'')},
          el('div',{class:'col-hd'},el('span',{},x.n),el('span',{class:'cnt'},String(colOf(x.k).length))),listFor(x.k,'list')))));
      }else{
        wrap.append(tabsBar(),listFor(curCol));
      }
    }
    return wrap;
  }


  function closeForm(extra){
    ui.view='board';ui.draft=null;ui.confirmDel=false;ui.formErr='';
    if(extra)Object.assign(ui,extra);
    redraw();
  }
  function nextUi(){
    return Object.assign({},ui,{view:'board',draft:null,confirmDel:false,formErr:'',err:''});
  }
  function saveDraft(){
    const d=Object.assign({},ui.draft);
    if(!(d.title||'').trim()){ui.formErr='请填写任务名称';redraw();return;}
    if(!d.id){d.id=uid();d.isNew=true;d.created=day();}
    ui.formErr='';
    commit(s=>applyDraft(s,d),nextUi()).catch(()=>{ui.formErr='保存失败，请重试';redraw();});
  }
  function deleteTask(){
    const id=ui.draft&&ui.draft.id;
    if(!id)return;
    commit(s=>withTasks(s,listOf(s).filter(x=>x.id!==id)),nextUi()).catch(()=>{ui.formErr='删除失败，请重试';redraw();});
  }

  function formView(){
    const d=ui.draft||{title:'',project:'',due:'',status:'todo',front:false};
    if(!ui.draft)ui.draft=d;
    const editing=!!d.id;
    const dw=weekDow(today);
    const quick=[['今天',0],['明天',1]];
    if(4-dw>1)quick.push(['本周五',4-dw]);
    if(6-dw>1)quick.push(['本周日',6-dw]);

    const titleInp=el('input',{class:'inp',type:'text',value:d.title,placeholder:'要做什么？',maxlength:'80','aria-label':'任务名称',
      oninput:(e)=>{d.title=e.target.value;},onkeydown:(e)=>{if(e.key==='Enter')saveDraft();}});
    const projInp=el('input',{class:'inp',type:'text',value:d.project,placeholder:'所属项目（可不填）',maxlength:'40','aria-label':'所属项目',
      oninput:(e)=>{d.project=e.target.value;},onkeydown:(e)=>{if(e.key==='Enter')saveDraft();}});
    const dueInp=el('input',{class:'inp',type:'date',value:d.due,'aria-label':'截止日期',
      oninput:(e)=>{d.due=e.target.value;},onchange:(e)=>{d.due=e.target.value;}});

